#include <stdio.h>
#include <stdint.h>

int64_t sumDivisors(int64_t lhs) {
    int64_t rhs = 0;
    for (int64_t i = 1; i <= lhs; i = i + 1) {
        if (lhs - (lhs / i) * i == 0) {
            rhs = rhs + i;
        }
    }
    return rhs;
}

int main() {
    printf("%ld\n", sumDivisors(1));
    printf("%ld\n", sumDivisors(2));
    printf("%ld\n", sumDivisors(6));
    printf("%ld\n", sumDivisors(12));
    printf("%ld\n", sumDivisors(28));
    return 0;
}

