import java.util.*;

public class Solution {
    public static long sumDivisors(long n) {
        long total = 0;
        for (long i = 1; i <= n; i++) {
            if (n % i == 0) {
                total += i;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        // Test case 1: n = 1
        System.out.println(sumDivisors(1));

        // Test case 2: n = 6 (perfect number)
        System.out.println(sumDivisors(6));

        // Test case 3: n = 12
        System.out.println(sumDivisors(12));

        // Test case 4: n = 28 (perfect number)
        System.out.println(sumDivisors(28));

        // Test case 5: n = 100
        System.out.println(sumDivisors(100));
    }
}
